function htmlExpandedNameChecks() {
  const HTML='http://www.w3.org/1999/xhtml', records=[];
  function run(name,action){try{records.push({name:name,value:action()});}catch(error){records.push({name:name,value:{error:error.name}});}}
  function make(name,attributes,doc){const node=(doc||document).createElementNS(HTML,'h:'+name);for(const key of Object.keys(attributes||{}))node.setAttribute(key,attributes[key]);return node;}
  for(const name of ['input','textarea','button','select','option','optgroup','form','fieldset','table','tbody','tr','td','ol','li','details','a','img','div','x-expanded-unknown'])run('interface-'+name,()=>{const n=make(name);return [n.constructor.name,n.nodeName,n.tagName,n.localName,n.prefix,n.namespaceURI];});
  for(const mode of ['foreign','null','colon-local','uppercase'])run('negative-'+mode,()=>{const n=mode==='foreign'?document.createElementNS('urn:foreign','h:input'):mode==='null'?document.createElementNS(null,'input'):mode==='colon-local'?document.createElement('h:input'):document.createElementNS(HTML,'h:INPUT');return [n.constructor.name,n.localName,typeof n.value,typeof n.checkValidity];});
  run('input-live-and-default',()=>{const n=make('input',{value:'initial'});n.value='typed';n.defaultValue='new';return [n.value,n.defaultValue,n.getAttribute('value'),n.type,n.size,n.tabIndex];});
  run('input-selection',()=>{const n=make('input',{value:'abcdef'});n.setSelectionRange(1,4,'backward');return [n.selectionStart,n.selectionEnd,n.selectionDirection];});
  run('input-reflection',()=>{const n=make('input');n.required=true;n.readOnly=true;n.disabled=true;n.maxLength=13;n.placeholder='hint';return [n.required,n.readOnly,n.disabled,n.maxLength,n.placeholder,n.getAttribute('required'),n.willValidate];});
  run('input-validation',()=>{const n=make('input',{required:''});const before=n.validity.valueMissing;n.value='ok';n.setCustomValidity('bad');return [before,n.validity.customError,n.checkValidity(),n.validationMessage];});
  run('input-number',()=>{const n=make('input',{type:'number',min:'1',step:'2',value:'3'});n.stepUp();return [n.value,n.valueAsNumber];});
  run('textarea-live-and-default',()=>{const n=make('textarea');n.textContent='one\r\ntwo';n.value='typed';n.defaultValue='new';return [n.value,n.defaultValue,n.textContent,n.type,n.cols,n.rows,n.textLength];});
  run('button-reflection',()=>{const n=make('button',{type:'button'});n.value='run';n.formMethod='post';return [n.type,n.value,n.formMethod,n.getAttribute('value')];});
  run('form-owner-and-elements',()=>{const f=make('form',{id:'expanded-form'}),n=make('input',{name:'field',value:'one'}),other=make('input',{form:'expanded-form',name:'outside'});f.append(n);document.body.append(f,other);const result=[n.form===f,other.form===f,f.elements.length,f.elements[0]===n,f.field===n,f.outside===other,f.length];f.remove();other.remove();return result;});
  run('form-reset',()=>{const f=make('form'),n=make('input',{value:'initial'}),t=make('textarea');t.textContent='default';f.append(n,t);n.value='typed';t.value='typed';f.reset();return [n.value,t.value];});
  run('form-requestSubmit',()=>{const f=make('form'),b=make('button'),n=make('input',{type:'submit'});f.append(b,n);let count=0,submitter=false;f.addEventListener('submit',e=>{e.preventDefault();count++;submitter=e.submitter===n;});document.body.append(f);f.requestSubmit(n);f.remove();return [count,submitter];});
  run('fieldset-first-legend',()=>{const f=make('fieldset',{disabled:''}),l=make('legend'),first=make('input'),second=make('input');l.append(first);f.append(l,second);return [first.willValidate,second.willValidate];});
  run('foreign-fieldset-not-disabled',()=>{const f=document.createElementNS('urn:foreign','fieldset'),n=make('input');f.setAttribute('disabled','');f.append(n);return n.willValidate;});
  run('foreign-form-not-owner',()=>{const f=document.createElementNS('urn:foreign','form'),n=make('input');f.append(n);return n.form===null;});
  run('select-options-live',()=>{const n=make('select'),g=make('optgroup'),a=make('option',{value:'a'}),b=make('option',{value:'b'});a.textContent='Alpha';b.textContent='Beta';g.append(a,b);n.append(g);const initial=[n.options.length,n.value,n.selectedIndex,a.index,b.index];b.selected=true;initial.push(n.value,n.selectedIndex,a.selected,b.selected,b.text,b.label);return initial;});
  run('option-form-owner',()=>{const f=make('form'),s=make('select'),o=make('option');s.append(o);f.append(s);return o.form===f;});
  run('select-multiple',()=>{const n=make('select',{multiple:''}),a=make('option',{value:'a',selected:''}),b=make('option',{value:'b',selected:''});n.append(a,b);return [n.type,n.options.length,n.selectedOptions.length,n.value,n.selectedIndex];});
  run('table-expanded-children',()=>{const n=make('table'),body=make('tbody'),row=make('tr'),cell=make('td');cell.colSpan=3;row.append(cell);body.append(row);n.append(body);return [n.rows.length,n.tBodies.length,row.cells.length,row.rowIndex,row.sectionRowIndex,cell.cellIndex,cell.colSpan];});
  run('table-borrowed-method',()=>{const n=make('table');const row=HTMLTableElement.prototype.insertRow.call(n);const cell=HTMLTableRowElement.prototype.insertCell.call(row);return [n.rows.length,row.cells.length,row.localName,cell.localName];});
  run('table-foreign-receiver',()=>{const n=document.createElementNS('urn:foreign','table');try{HTMLTableElement.prototype.insertRow.call(n);return 'accepted';}catch(error){return error.name;}});
  run('list-reflection',()=>{const n=make('ol'),li=make('li');n.start=7;n.reversed=true;li.value=11;return [n.start,n.reversed,n.getAttribute('start'),li.value,li.getAttribute('value')];});
  run('details-group',()=>{const a=make('details',{name:'expanded-group',open:''}),b=make('details',{name:'expanded-group'});document.body.append(a,b);b.open=true;const result=[a.open,b.open];a.remove();b.remove();return result;});
  run('link-and-image-reflection',()=>{const a=make('a',{href:'/expanded'}),img=make('img',{alt:'caption'});return [a.href.endsWith('/expanded'),a.tabIndex,a.draggable,img.alt,img.draggable];});
  run('clone-live-state',()=>{const n=make('input',{value:'initial'});n.value='typed';const c=n.cloneNode(true);return [c.value,c.defaultValue,c.nodeName,c.localName,c.prefix,c.namespaceURI];});
  run('xml-document-controls',()=>{const d=document.implementation.createDocument(HTML,'h:html',null),n=make('input',{value:'one'},d);n.value='typed';return [n.constructor.name,n.nodeName,n.value,n.defaultValue,n.type];});
  run('autonomous-prefixed-upgrade',()=>{class ExpandedProbe extends HTMLElement{constructor(){super();this.upgraded=17;}}customElements.define('x-expanded-probe',ExpandedProbe);const n=make('x-expanded-probe');return [n instanceof ExpandedProbe,n.upgraded,n.localName,n.prefix];});
  run('prefixed-upgrade-existing',()=>{const n=make('x-expanded-existing');document.body.append(n);class ExistingProbe extends HTMLElement{connectedCallback(){this.connected=1;}}customElements.define('x-expanded-existing',ExistingProbe);const result=[n instanceof ExistingProbe,n.connected,n.localName,n.prefix];n.remove();return result;});
  run('formdata-expanded-controls',()=>{const f=make('form'),n=make('input',{name:'field',value:'one'}),s=make('select',{name:'choice'}),o=make('option',{value:'a',selected:''}),b=make('button',{name:'submit',value:'send'});s.append(o);f.append(n,s,b);n.value='typed';return Array.from(new FormData(f,b).entries());});
  run('formdata-prefixed-datalist-exclusion',()=>{const f=make('form'),l=make('datalist'),n=make('input',{name:'excluded',value:'one'}),kept=make('input',{name:'kept',value:'two'});l.append(n);f.append(l,kept);return Array.from(new FormData(f).entries());});
  run('formdata-unprefixed-datalist-control',()=>{const f=make('form'),l=document.createElement('datalist'),n=make('input',{name:'excluded',value:'one'}),kept=make('input',{name:'kept',value:'two'});l.append(n);f.append(l,kept);return Array.from(new FormData(f).entries());});
  run('formdata-unprefixed-input-control',()=>{const f=make('form'),l=document.createElement('datalist'),n=document.createElement('input'),kept=make('input',{name:'kept',value:'two'});n.name='excluded';n.value='one';l.append(n);f.append(l,kept);return Array.from(new FormData(f).entries());});
  run('form-named-radio-list',()=>{const f=make('form'),a=make('input',{name:'group',type:'radio',value:'a'}),b=make('input',{name:'group',type:'radio',value:'b'});f.append(a,b);f.group.value='b';return [f.group.length,f.group.value,a.checked,b.checked];});
  run('document-window-named-form',()=>{const f=make('form',{name:'expandedNamedForm'});document.body.append(f);const value=[document.expandedNamedForm===f,window.expandedNamedForm===f];f.remove();return value;});
  run('mutation-keeps-qualified-source-name',()=>{const n=make('input'),observer=new MutationObserver(()=>{});observer.observe(n,{attributes:true,attributeOldValue:true});n.required=true;n.name='expanded';const records=observer.takeRecords().map(r=>[r.type,r.attributeName,r.oldValue,r.target===n]);observer.disconnect();return [n.nodeName,n.localName,n.prefix,records];});
  run('custom-prefixed-observed-attributes',()=>{let calls=[];class ObservedProbe extends HTMLElement{static get observedAttributes(){return ['data-x'];}attributeChangedCallback(name,oldValue,value){calls.push([name,oldValue,value,this.localName,this.prefix]);}}customElements.define('x-expanded-observed',ObservedProbe);const n=make('x-expanded-observed');n.setAttribute('data-x','one');n.removeAttribute('data-x');return calls;});
  run('form-associated-prefixed-custom-element',()=>{class FormProbe extends HTMLElement{static formAssociated=true;constructor(){super();this.internals=this.attachInternals();this.internals.setFormValue('custom');}}customElements.define('x-expanded-face',FormProbe);const f=make('form'),n=make('x-expanded-face',{name:'custom-field'});f.append(n);document.body.append(f);const value=[n.internals.form===f,f.elements.length,Array.from(new FormData(f).entries())];f.remove();return value;});
  return records;
}
function htmlExpandedPseudoChecks(){
  const H='http://www.w3.org/1999/xhtml',records=[];
  function check(name,ns,local,attrs,pseudos){const n=document.createElementNS(ns,(ns===H?'h:':'')+local);for(const key of Object.keys(attrs))n.setAttribute(key,attrs[key]);records.push({name:name,value:pseudos.map(p=>n.matches(p))});}
  check('input-states',H,'input',{required:'',disabled:'',placeholder:'hint'},[':required',':optional',':disabled',':enabled',':read-only',':read-write',':placeholder-shown',':invalid',':valid']);
  check('checked-radio',H,'input',{type:'radio',checked:''},[':checked',':indeterminate',':defined']);
  check('option-selected',H,'option',{selected:''},[':checked',':disabled',':enabled',':defined']);
  check('details-open',H,'details',{open:''},[':open',':defined']);check('link',H,'a',{href:'#'},[':link',':any-link',':defined']);
  check('progress-empty',H,'progress',{},[':indeterminate',':defined']);
  check('foreign-input', 'urn:foreign','input',{required:'',disabled:'',checked:''},[':required',':optional',':disabled',':enabled',':checked',':defined',':read-only']);
  check('null-details',null,'details',{open:''},[':open',':defined']);
  return records;
}
